// Accessible desktop controls share the studio's existing media and audio engine.
export function createStudioDesktop(api){
 const sessionAPI=window.lotusSession;
 const videoHome=document.querySelector('#studio-mv')?.parentElement;
 const dialog=document.createElement('dialog');dialog.className='studio-desktop';dialog.setAttribute('aria-label','Lotus desktop');
 dialog.innerHTML=`<div class="desktop-menubar"><b>◈ &nbsp; Lotus Studio</b><span>Music &nbsp; Session &nbsp; Window</span><time></time></div><section class="mac-window"><header class="mac-toolbar"><div class="mac-lights"><button data-close aria-label="Close computer">×</button><button data-minimize aria-label="Return to the room">−</button><button data-full aria-label="Resize computer window">＋</button></div><strong>My listening room</strong><span>LOTUS FLOW</span></header><div class="mac-content"><aside><p>LIBRARY</p><button data-mode="music">♫ &nbsp; My music</button><button data-mode="video">▷ &nbsp; Music films</button><button data-mode="session">≋ &nbsp; Sound lab</button><p class="mac-side-note">Expression<br>over impression.</p></aside><main><div class="mac-library-heading"><div><small>LOTUS FLOW / STUDIO</small><h2>My music.</h2></div><input type="search" aria-label="Search studio library" placeholder="Search library"></div><div class="mac-film" hidden></div><div class="mac-tracks"></div><div class="mac-session" hidden></div></main></div><footer class="mac-transport"><div><img alt=""><span><strong class="mac-track-title"></strong><small class="mac-track-artist"></small></span></div><section><div class="mac-playback"><button data-prev aria-label="Previous song">⏮︎</button><button data-play aria-label="Play or pause song">▶︎</button><button data-next aria-label="Next song">⏭︎</button></div><label class="mac-progress"><time>0:00</time><input type="range" min="0" max="1000" value="0" aria-label="Desktop playback position"><time>0:00</time></label></section><label class="mac-volume">♫ <input type="range" min="0" max="100" value="70" aria-label="Desktop volume"></label></footer></section><nav class="mac-dock" aria-label="Desktop apps"><button data-mode="music" aria-label="Open Music">♫</button><button data-mode="video" aria-label="Open Music Films">▷</button><button data-mode="session" aria-label="Open Sound Lab">≋</button><button data-close aria-label="Return to Studio">⌂</button></nav>`;
 document.body.append(dialog);
 const $=s=>dialog.querySelector(s),player=()=>window.lotusStudioMedia;let interval=0,lastTrack='',lastMode='',lastFocus=null,drag=null,roomScroll=0,closing=false;
 const format=n=>`${Math.floor((n||0)/60)}:${String(Math.floor((n||0)%60)).padStart(2,'0')}`;
 function list(){const p=player();if(!p)return;const mode=p.mode,q=$('input[type=search]').value.toLowerCase();$('.mac-tracks').replaceChildren();$('.mac-tracks').hidden=mode==='session';$('.mac-session').hidden=mode!=='session';$('input[type=search]').hidden=mode==='session';$('.mac-transport').hidden=mode==='session';$('h2').textContent=mode==='music'?'My music.':mode==='video'?'Music films.':'Sound lab.';dialog.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mode===mode)));
  $('.mac-film').hidden=mode!=='video';if(mode==='video'){const video=document.querySelector('#studio-mv');if(video.parentElement!==$('.mac-film'))$('.mac-film').append(video);video.controls=true;}
  if(mode==='session')return;
  p.collection.filter(t=>`${t.title} ${t.artist}`.toLowerCase().includes(q)).forEach(t=>{const b=document.createElement('button');b.className='mac-track';b.dataset.track=t.id;b.setAttribute('aria-current',String(t.id===p.track.id));const img=new Image();img.src=t.image||api.tracks.find(a=>a.id===t.id)?.image||'';img.alt='';const label=document.createElement('span'),title=document.createElement('strong'),artist=document.createElement('small');title.textContent=t.title;artist.textContent=t.artist;label.append(title,artist);const kind=document.createElement('small');kind.textContent=mode==='video'?'FILM':t.audioKind==='full'?'FULL TRACK':'PREVIEW';b.append(img,label,kind);b.onclick=()=>{p.choose(t.id);sync()};$('.mac-tracks').append(b)});
 }
 function sync(){if(!dialog.open)return;const p=player();if(!p)return;if(lastMode!==p.mode){lastMode=p.mode;list()}const m=p.media,t=p.track;const key=p.mode+t.id;if(lastTrack!==key){lastTrack=key;$('.mac-transport img').src=t.image||api.tracks.find(a=>a.id===t.id)?.image||'';$('.mac-track-title').textContent=t.title;$('.mac-track-artist').textContent=t.artist;dialog.querySelectorAll('[data-track]').forEach(b=>b.setAttribute('aria-current',String(b.dataset.track===t.id)))}
  $('[data-play]').textContent=m.paused?'▶︎':'Ⅱ';$('.mac-progress input').value=Number.isFinite(m.duration)?m.currentTime/m.duration*1000:0;const times=dialog.querySelectorAll('.mac-progress time');times[0].textContent=format(m.currentTime);times[1].textContent=format(Number.isFinite(m.duration)?m.duration:0);$('.mac-volume input').value=m.volume*100;$('.desktop-menubar time').textContent=new Date().toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'});
 }
 function close(){if(closing||!dialog.open)return;closing=true;clearInterval(interval);const finish=()=>{const video=document.querySelector('#studio-mv');if(videoHome&&video){video.controls=false;videoHome.append(video)}dialog.close();document.body.classList.remove('desktop-open');window.scrollTo({top:roomScroll,behavior:'instant'});lastFocus?.focus({preventScroll:true});closing=false;};if(matchMedia('(prefers-reduced-motion: reduce)').matches){finish();return}dialog.animate([{opacity:1,transform:'scale(1)'},{opacity:0,transform:'scale(.98)'}],{duration:280,easing:'ease-in'}).finished.then(finish,finish)}
 function open(){if(dialog.open)return;player()?.openScreen();roomScroll=scrollY;lastFocus=document.activeElement;dialog.showModal();document.body.classList.add('desktop-open');lastMode='';lastTrack='';sync();interval=setInterval(sync,200)}
 dialog.addEventListener('cancel',e=>{e.preventDefault();close()});dialog.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.matches('[data-close],[data-minimize]'))close();if(b.hasAttribute('data-full'))$('.mac-window').classList.toggle('mac-maximized');if(b.dataset.mode){$('input[type=search]').value='';player().setMode(b.dataset.mode);sync()}if(b.hasAttribute('data-play'))player().toggle();if(b.hasAttribute('data-prev'))player().advance(-1);if(b.hasAttribute('data-next'))player().advance(1)});
 $('input[type=search]').addEventListener('input',list);$('.mac-progress input').addEventListener('input',e=>player().seekTo(Number(e.target.value)/1000));$('.mac-volume input').addEventListener('input',e=>player().volume(Number(e.target.value)/100));
 const session=$('.mac-session');const play=document.createElement('button');play.className='mac-session-play';play.textContent='▶︎ Play / stop session';play.onclick=()=>sessionAPI.togglePlayback();session.append(play);
 const strips=document.createElement('div');strips.className='mac-mixer';session.append(strips);
 sessionAPI.channels.forEach(c=>{const strip=document.createElement('label');strip.className='mac-channel';const name=document.createElement('strong');name.textContent=c.name;const range=document.createElement('input');range.type='range';range.min='0';range.max='100';range.value=c.value;range.setAttribute('aria-label',c.name+' volume');const value=document.createElement('output');value.textContent=Math.round(c.value)+'%';range.oninput=()=>{sessionAPI.setChannel(c.id,{volume:Number(range.value)});value.textContent=range.value+'%'};strip.append(name,range,value);strips.append(strip)});
 const bar=$('.mac-toolbar'),win=$('.mac-window');bar.addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;const b=win.getBoundingClientRect();drag={x:e.clientX,y:e.clientY,dx:parseFloat(win.style.getPropertyValue('--dx'))||0,dy:parseFloat(win.style.getPropertyValue('--dy'))||0,left:b.left,right:b.right,top:b.top,bottom:b.bottom};bar.setPointerCapture(e.pointerId)});
 bar.addEventListener('pointermove',e=>{if(!drag)return;const dx=Math.max(-drag.left+12,Math.min(innerWidth-drag.right-12,e.clientX-drag.x)),dy=Math.max(35-drag.top,Math.min(innerHeight-drag.bottom-68,e.clientY-drag.y));win.style.setProperty('--dx',drag.dx+dx+'px');win.style.setProperty('--dy',drag.dy+dy+'px')});for(const event of ['pointerup','pointercancel'])bar.addEventListener(event,()=>drag=null);
 const button=document.createElement('button');button.className='studio-computer-button';button.textContent='⌘ USE COMPUTER';button.onclick=open;document.querySelector('.studio-view-buttons').append(button);
 window.addEventListener('lotus-room-change',e=>{if(!e.detail&&dialog.open)close()});return{open,close};
}
